import { getUser } from './user.js';
export function call(): string {
  return getUser();
}

import assert from 'node:assert';
import { readFileSync } from 'node:fs';
const user = readFileSync('src/user.ts', 'utf8');
const api = readFileSync('src/api.ts', 'utf8');
assert.ok(user.includes('fetchUser'), 'user.ts must define fetchUser');
assert.ok(!user.includes('getUser'), 'user.ts must not keep the old name');
assert.ok(api.includes('fetchUser'), 'api.ts must import fetchUser');
console.log('ok');
